<script setup>
import { ref,computed,onMounted } from 'vue';import {useRouter} from 'vue-router';import {api,send,money} from '../api';
const siteOrigin=window.location.origin;const router=useRouter(),me=ref(null),tab=ref('dashboard'),loading=ref(true),error=ref(''),toast=ref(''),dashboard=ref({totals:[],recent:[]}),bookings=ref([]),total=ref(0),page=ref(1),status=ref(''),q=ref(''),services=ref([]),daysOff=ref([]),dayInput=ref(''),editService=ref(null),merchantForm=ref({name:'',intro:'',address:'',phone:''}),showMenu=ref(false),working=ref(false);
const nav=[['dashboard','▦','工作台概览'],['bookings','▤','预约管理'],['services','◈','拍摄服务'],['schedule','▦','休息日设置'],['settings','⚙','工作室设置']];const names={pending:'待确认',confirmed:'已确认',completed:'已完成',cancelled:'已取消',rejected:'已拒绝'};const available={pending:[['confirmed','确认预约'],['rejected','拒绝预约'],['cancelled','取消预约']],confirmed:[['completed','标记完成'],['cancelled','取消预约']]};const counts=computed(()=>Object.fromEntries(dashboard.value.totals.map(x=>[x.status,x.count])));
function flash(message){toast.value=message;setTimeout(()=>toast.value='',3500)}
async function load(){error.value='';try{if(tab.value==='dashboard')dashboard.value=await api('/admin/dashboard');if(tab.value==='bookings'){const r=await api('/admin/bookings?'+new URLSearchParams({page:page.value,status:status.value,q:q.value}));bookings.value=r.items;total.value=r.total}if(tab.value==='services')services.value=(await api('/admin/services')).items;if(tab.value==='schedule')daysOff.value=(await api('/admin/days-off')).dates;if(tab.value==='settings')merchantForm.value={...merchantForm.value,...me.value.merchant}}catch(e){error.value=e.message}}
async function navigate(to){tab.value=to;showMenu.value=false;await load()}
onMounted(async()=>{try{me.value=await api('/auth/me');await load()}catch(e){if(e.message==='请先登录')router.replace('/login');else error.value=e.message}finally{loading.value=false}});
async function logout(){await send('/auth/logout',{});router.replace('/login')}
async function changeStatus(b,next){if(!confirm(`确定将 ${b.code} 修改为「${names[next]}」吗？`))return;try{await send(`/admin/bookings/${b.id}/status`,{status:next},'PATCH');flash('订单状态已更新');await load()}catch(e){flash(e.message)}}
function newService(){editService.value={title:'',description:'',price_cents:39900,duration_minutes:90,image_url:'',active:true}}
async function saveService(){if(working.value)return;working.value=true;try{const s=editService.value;await send('/admin/services'+(s.id?'/'+s.id:''),{...s,price_cents:Number(s.price_cents),duration_minutes:Number(s.duration_minutes)},s.id?'PATCH':'POST');editService.value=null;flash('服务已保存');await load()}catch(e){flash(e.message)}finally{working.value=false}}
async function disableService(s){if(!confirm('确定下架该服务吗？历史订单仍会保留。'))return;try{await api('/admin/services/'+s.id,{method:'DELETE'});flash('服务已下架');await load()}catch(e){flash(e.message)}}
async function saveDays(){try{await send('/admin/days-off',{dates:daysOff.value},'PUT');flash('休息日已保存')}catch(e){flash(e.message)}}
function addDay(){if(!/^\d{4}-\d{2}-\d{2}$/.test(dayInput.value))return;if(!daysOff.value.includes(dayInput.value))daysOff.value.push(dayInput.value);daysOff.value.sort();dayInput.value=''}
async function saveMerchant(){try{await send('/admin/merchant',merchantForm.value,'PATCH');me.value.merchant={...merchantForm.value,slug:me.value.merchant.slug};flash('工作室信息已保存')}catch(e){flash(e.message)}}
function exportCsv(){const head=['预约编号','联系人','电话','服务项目','预约日期','时段','状态','备注'];const rows=bookings.value.map(b=>[b.code,b.contact_name,b.contact_phone,b.service_title,b.preferred_date,b.preferred_time,names[b.status],b.note]);const csv='\ufeff'+[head,...rows].map(row=>row.map(v=>'"'+( /^[=+@\-]/.test(String(v??''))?"'":'')+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`预约记录-当前页-${Date.now()}.csv`;a.click();URL.revokeObjectURL(url)}
</script>
<template><div v-if="loading" class="center-state">正在检查登录状态…</div><div v-else class="admin-layout"><aside class="sidebar" :class="{'sidebar-open':showMenu}"><div class="sidebar-brand"><span class="brand-icon">◈</span><span>约客助手<small>STUDIO CONSOLE</small></span></div><div class="sidebar-section">WORKSPACE</div><button v-for="item in nav" :key="item[0]" class="nav-item" :class="{active:tab===item[0]}" @click="navigate(item[0])"><span class="nav-glyph">{{item[1]}}</span>{{item[2]}}<span v-if="tab===item[0]" class="nav-dot"></span></button><div class="sidebar-bottom"><div class="account-card"><span class="account-avatar">{{me?.merchant.name.slice(0,1)}}</span><div><strong>{{me?.merchant.name}}</strong><small>{{me?.user.email}}</small></div></div><button class="logout-btn" @click="logout">退出登录 ↗</button></div></aside><div v-if="showMenu" class="mobile-backdrop" @click="showMenu=false"></div><div class="admin-main"><header class="admin-topbar"><button class="menu-button" @click="showMenu=!showMenu">☰</button><div class="crumb">工作空间 <span>/</span> {{nav.find(x=>x[0]===tab)?.[2]}}</div><div class="top-actions"><a :href="`/s/${me?.merchant.slug}`" target="_blank" rel="noopener noreferrer" class="outline-action">预览预约主页 ↗</a><span class="top-avatar">{{me?.merchant.name.slice(0,1)}}</span></div></header><main class="admin-content"><div class="admin-heading"><div><div class="eyebrow dark">YOUR STUDIO, IN CONTROL</div><h1>{{nav.find(x=>x[0]===tab)?.[2]}}<span class="dot">.</span></h1><p class="muted">{{tab==='dashboard'?'欢迎回来，今天也让每一次预约井然有序。':tab==='bookings'?'查看客户预约申请，及时确认每一份期待。':tab==='services'?'管理公开展示的拍摄服务与定价。':tab==='schedule'?'设置不可接受预约申请的日期。':'完善工作室公开展示的信息。'}}</p></div><button v-if="tab==='services'&&me?.user.role!=='staff'" class="button primary" @click="newService">＋ 新增服务</button></div><div v-if="error" class="alert">{{error}} <button @click="load">重试</button></div>
<section v-if="tab==='dashboard'"><div class="stat-grid"><div class="stat-card"><span>累计预约</span><strong>{{Object.values(counts).reduce((a,b)=>a+b,0)}}</strong><small>全部预约申请</small><span class="stat-mark">↗</span></div><div class="stat-card"><span>待处理预约</span><strong>{{counts.pending||0}}</strong><small>建议优先联系确认</small><span class="stat-mark accent">◷</span></div><div class="stat-card"><span>已确认预约</span><strong>{{counts.confirmed||0}}</strong><small>等待服务进行</small><span class="stat-mark">✓</span></div><div class="stat-card"><span>已完成预约</span><strong>{{counts.completed||0}}</strong><small>历史完成总数</small><span class="stat-mark">◈</span></div></div><div class="panel"><div class="panel-head"><div><h2>最新预约</h2><p>近期提交的预约申请</p></div><button class="text-button" @click="navigate('bookings')">查看全部 ↗</button></div><div v-if="!dashboard.recent.length" class="empty">还没有预约申请。可以先分享工作室主页链接。</div><div v-for="b in dashboard.recent" :key="b.id" class="recent-row"><div class="recent-icon">◈</div><div class="recent-info"><strong>{{b.service_title}}</strong><span>{{b.code}} · {{b.preferred_date}} {{b.preferred_time}}</span></div><span class="status-pill" :class="b.status">{{names[b.status]}}</span></div></div></section>
<section v-if="tab==='bookings'" class="panel"><div class="panel-head"><div><h2>全部预约</h2><p>共 {{total}} 条记录 · 每页20条</p></div><button class="outline-action" @click="exportCsv" :disabled="!bookings.length">↓ 导出当前页</button></div><div class="filter-row"><input v-model="q" placeholder="搜索编号 / 姓名 / 电话" @keyup.enter="page=1;load()"/><select v-model="status" @change="page=1;load()"><option value="">全部状态</option><option v-for="(name,key) in names" :key="key" :value="key">{{name}}</option></select><button class="button dark" @click="page=1;load()">查询</button></div><div class="table-scroll"><table class="admin-table"><thead><tr><th>客户 / 编号</th><th>预约服务</th><th>预约时间</th><th>联系方式</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="b in bookings" :key="b.id"><td><strong>{{b.contact_name}}</strong><small>{{b.code}}</small></td><td>{{b.service_title}}</td><td>{{b.preferred_date}}<small>{{b.preferred_time}}</small></td><td>{{b.contact_phone}}</td><td><span class="status-pill" :class="b.status">{{names[b.status]}}</span></td><td><select v-if="available[b.status]?.length" class="change-select" :value="''" @change="changeStatus(b,$event.target.value);$event.target.value='' "><option value="">处理订单</option><option v-for="act in available[b.status]" :key="act[0]" :value="act[0]">{{act[1]}}</option></select><span v-else class="muted">—</span></td></tr></tbody></table><div v-if="!bookings.length" class="empty">没有符合条件的预约记录</div></div><div class="pagination"><span>第 {{page}} 页 / 共 {{Math.max(1,Math.ceil(total/20))}} 页</span><div><button :disabled="page===1" @click="page--;load()">上一页</button><button :disabled="page*20>=total" @click="page++;load()">下一页</button></div></div></section>
<section v-if="tab==='services'"><div class="services-admin"><article v-for="s in services" :key="s.id" class="panel service-admin-card"><div class="sa-icon">◈</div><div class="sa-body"><div class="sa-top"><h3>{{s.title}}</h3><span class="status-pill" :class="s.active?'confirmed':'cancelled'">{{s.active?'上架中':'已下架'}}</span></div><p>{{s.description||'暂无描述'}}</p><div class="sa-info">{{money(s.price_cents)}} · {{s.duration_minutes}}分钟</div><div v-if="me?.user.role!=='staff'" class="sa-actions"><button @click="editService={...s,active:!!s.active}">编辑服务</button><button v-if="s.active" @click="disableService(s)">下架</button></div></div></article></div><div v-if="!services.length" class="empty">还没有任何服务，点击右上角新增。</div></section>
<section v-if="tab==='schedule'" class="panel form-panel"><div class="panel-head"><div><h2>休息日管理</h2><p>休息日不会出现在可接受申请的日期中。</p></div></div><div class="filter-row"><input v-model="dayInput" type="date"/><button class="button dark" @click="addDay">添加休息日</button></div><div class="day-chips"><span v-for="d in daysOff" :key="d" class="day-chip">{{d}} <button @click="daysOff=daysOff.filter(x=>x!==d)">×</button></span><p v-if="!daysOff.length" class="muted">没有设置休息日。</p></div><button v-if="me?.user.role!=='staff'" class="button primary" @click="saveDays">保存休息日设置</button></section>
<section v-if="tab==='settings'" class="panel form-panel"><div class="panel-head"><div><h2>工作室基本信息</h2><p>以下名称、简介和地址会显示在客户预约主页。</p></div></div><form class="settings-form" @submit.prevent="saveMerchant"><label>工作室名称<input v-model="merchantForm.name" required maxlength="80" :disabled="me?.user.role==='staff'"/></label><label>工作室简介<textarea v-model="merchantForm.intro" maxlength="500" rows="4" :disabled="me?.user.role==='staff'"></textarea></label><label>拍摄地址 / 说明<input v-model="merchantForm.address" maxlength="200" :disabled="me?.user.role==='staff'"/></label><label>商家联系信息（后台配置）<input v-model="merchantForm.phone" maxlength="50" :disabled="me?.user.role==='staff'"/></label><label>商家主页链接<input :value="`${siteOrigin}/s/${me?.merchant.slug}`" readonly/></label><button v-if="me?.user.role!=='staff'" class="button primary">保存设置</button></form></section>
</main></div><div v-if="toast" class="toast">{{toast}}</div><div v-if="editService" class="modal-overlay" @click.self="editService=null"><form class="edit-modal" @submit.prevent="saveService"><div class="modal-head"><h2>{{editService.id?'编辑拍摄服务':'新增拍摄服务'}}</h2><button type="button" @click="editService=null">✕</button></div><label>服务名称<input v-model="editService.title" required maxlength="80"/></label><label>服务描述<textarea v-model="editService.description" maxlength="1000" rows="4"></textarea></label><div class="form-grid"><label>参考价格（分）<input v-model.number="editService.price_cents" type="number" min="0" max="100000000" required/></label><label>预计时长（分钟）<input v-model.number="editService.duration_minutes" type="number" min="15" max="1440" required/></label></div><label>封面图片URL（HTTPS，可选）<input v-model="editService.image_url" placeholder="https://..."/></label><label class="consent"><input v-model="editService.active" type="checkbox"/> 上架此服务</label><button type="submit" :disabled="working" class="button primary">{{working?'保存中…':'保存服务'}}</button></form></div></div></template>
